import os

transform_code = '''"""Task transformation function for task-a0e91fa9.

Rule: Find a separator (uniform row or column with non-zero value).
- For vertical separator: split into left/right, output 2 where left[c] == 1 AND right[c] == 9
- For horizontal separator: split into top/bottom, output 2 where top[r][c] == 4 AND bottom[r][c] == 5
"""

def transform(grid):
    num_rows = len(grid)
    num_cols = len(grid[0])

    # Horizontal separator detection
    sep_row = None
    for r in range(num_rows):
        if all(grid[r][c] == grid[r][0] for c in range(num_cols)) and not all(v == 0 for v in grid[r]):
            if num_rows // 2 - 10 <= r <= num_rows // 2 + 10:
                sep_row = r
                break

    # Vertical separator detection
    sep_col = None
    if sep_row is None:
        for c in range(num_cols):
            col_vals = [grid[r][c] for r in range(num_rows)]
            if all(v == col_vals[0] for v in col_vals) and not all(v == 0 for v in col_vals):
                if num_cols // 2 - 10 <= c <= num_cols // 2 + 10:
                    sep_col = c
                    break

    # Vertical separator case
    if sep_col is not None:
        sep_col = 10
        left = [[grid[r][c] for c in range(sep_col)] for r in range(num_rows)]
        right = [[grid[r][c] for c in range(sep_col + 1, num_cols)] for r in range(num_rows)]

        result = []
        for r in range(num_rows):
            row = []
            for c in range(len(left[r])):
                if left[r][c] == 1 and right[r][c] == 9:
                    row.append(2)
                else:
                    row.append(0)
            result.append(row)

    # Horizontal separator case
    elif sep_row is not None:
        top = [grid[i] for i in range(sep_row)]
        bottom = [grid[i] for i in range(sep_row + 1, num_rows)]

        result = []
        for r in range(len(top)):
            row = []
            for c in range(len(top[r])):
                if top[r][c] == 4 and bottom[r][c] == 5:
                    row.append(2)
                else:
                    row.append(0)
            result.append(row)

    else:
        result = [[0] * num_cols for _ in range(num_rows)]

    return result


def f(grid):
    return transform(grid)
